PRAGMA foreign_keys=OFF;
CREATE TABLE "User" ("id" TEXT PRIMARY KEY NOT NULL, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "RefreshToken" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" DATETIME NOT NULL, "revokedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Profile" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL UNIQUE, "goals" TEXT NOT NULL DEFAULT '[]', "proficiency" TEXT NOT NULL DEFAULT 'beginner', "dailyMinutes" INTEGER NOT NULL DEFAULT 15, "timezone" TEXT NOT NULL DEFAULT 'UTC', "ieltsIntent" BOOLEAN NOT NULL DEFAULT false, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Course" ("id" TEXT PRIMARY KEY NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "level" TEXT NOT NULL, "position" INTEGER NOT NULL UNIQUE, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Lesson" ("id" TEXT PRIMARY KEY NOT NULL, "courseId" TEXT NOT NULL, "title" TEXT NOT NULL, "summary" TEXT NOT NULL, "content" TEXT NOT NULL, "durationMin" INTEGER NOT NULL, "position" INTEGER NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, UNIQUE("courseId", "position"), FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON DELETE CASCADE);
CREATE TABLE "LessonProgress" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "lessonId" TEXT NOT NULL, "completedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("userId", "lessonId"), FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, FOREIGN KEY ("lessonId") REFERENCES "Lesson"("id") ON DELETE CASCADE);
CREATE TABLE "VocabularyItem" ("id" TEXT PRIMARY KEY NOT NULL, "word" TEXT NOT NULL UNIQUE, "partOfSpeech" TEXT NOT NULL, "definition" TEXT NOT NULL, "example" TEXT NOT NULL, "level" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "ReviewSchedule" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "vocabularyId" TEXT NOT NULL, "dueAt" DATETIME NOT NULL, "intervalDays" INTEGER NOT NULL DEFAULT 0, "repetitions" INTEGER NOT NULL DEFAULT 0, "lastGrade" TEXT, "lastReviewedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, UNIQUE("userId", "vocabularyId"));
CREATE TABLE "SpeakingSession" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "prompt" TEXT NOT NULL, "transcript" TEXT, "feedback" TEXT, "audioUrl" TEXT, "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" DATETIME, "deletedAt" DATETIME);
CREATE TABLE "Conversation" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "scenarioId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "summary" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" DATETIME);
CREATE TABLE "ConversationTurn" ("id" TEXT PRIMARY KEY NOT NULL, "conversationId" TEXT NOT NULL, "role" TEXT NOT NULL, "transcript" TEXT, "text" TEXT NOT NULL, "audioUrl" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "IeltsAttempt" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "mockId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'in_progress', "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" DATETIME, "feedback" TEXT);
CREATE TABLE "IeltsAttemptResponse" ("id" TEXT PRIMARY KEY NOT NULL, "attemptId" TEXT NOT NULL, "sectionId" TEXT NOT NULL, "transcript" TEXT, "audioUrl" TEXT, "feedback" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, UNIQUE("attemptId", "sectionId"));
CREATE TABLE "SkillSnapshot" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "skill" TEXT NOT NULL, "value" REAL, "source" TEXT NOT NULL, "recordedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "StreakState" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL UNIQUE, "currentDays" INTEGER NOT NULL DEFAULT 0, "longestDays" INTEGER NOT NULL DEFAULT 0, "lastActivityOn" DATETIME, "reminderTime" TEXT, "reminderDays" TEXT NOT NULL DEFAULT '[]', "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Referral" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL UNIQUE, "code" TEXT NOT NULL UNIQUE, "referredById" TEXT, "redeemedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PurchaseEntitlement" ("id" TEXT PRIMARY KEY NOT NULL, "userId" TEXT NOT NULL, "productId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'inactive', "source" TEXT NOT NULL, "purchaseToken" TEXT UNIQUE, "startsAt" DATETIME, "expiresAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "ReviewSchedule_userId_dueAt_idx" ON "ReviewSchedule"("userId", "dueAt");
PRAGMA foreign_keys=ON;
